/*
 *  ms20.cpp — MS-20 style voice for the Korg NTS-1, generated by korgTools.
 *
 *  Same maths as the korgTools browser preview and the drumlogue build:
 *  two PolyBLEP oscillators (ring mod, noise, analog drift), a saturating
 *  high-pass into a resonant low-pass, feedback drive, ADSR, pitch drop,
 *  triangle LFO and glide.
 *
 *  The NTS-1 gives a user oscillator six knobs. Those six are live; every
 *  other setting is baked in from the screen you downloaded this from.
 */
#include "userosc.h"
#include <cmath>
#include <cstdint>

#define NPARAMS 24

static const float kSR = 48000.f;
static const float kPi = 3.14159265358979f;

/* ---- the sound you were hearing when you pressed download ---- */
static int32_t p_[NPARAMS] = {45, 20, 0, 0, 1, 1, 0, 12, 100, 90, 0, 0, 70, 70, 80, 75, 20, 0, 15, 25, 0, 40, 50, 80};

/* ---- the six the NTS-1 lets you turn ---- */
static const int32_t kLiveIdx[6] = {0, 1, 16, 12, 15, 23};
static const int32_t kLiveMin[6] = {0, 0, -100, 0, 0, 0};
static const int32_t kLiveMax[6] = {100, 100, 100, 100, 100, 100};

static inline void setLive(int which, uint16_t raw) {
  int32_t v = (int32_t)(int16_t)raw;           // negative ranges arrive as two's complement
  if (v < kLiveMin[which]) v = kLiveMin[which];
  if (v > kLiveMax[which]) v = kLiveMax[which];
  p_[kLiveIdx[which]] = v;
}

/* ---- voice state: fixed size, no allocation ---- */
static float ph1_ = 0, ph2_ = 0, lfoPh_ = 0;
static float h1_ = 0, h2_ = 0, l1_ = 0, l2_ = 0;
static float d1_ = 0, d2_ = 0, fbY_ = 0, penv_ = 0;
static float env_ = 0, bend_ = 0;
static float cur_ = 60.f, target_ = 60.f;
static int stage_ = 0;                          // 0 idle 1 attack 2 decay 3 release
static uint32_t seed_ = 0x12345678;

static inline float fastTanh(float x) {
  if (x < -3.f) return -1.f;
  if (x > 3.f) return 1.f;
  const float x2 = x * x;
  return x * (27.f + x2) / (27.f + 9.f * x2);
}
static inline float blep(float t, float dt) {
  if (t < dt) { t /= dt; return t + t - t * t - 1.f; }
  if (t > 1.f - dt) { t = (t - 1.f) / dt; return t * t + t + t + 1.f; }
  return 0.f;
}
static inline float clamp4(float x) { return x > 4.f ? 4.f : (x < -4.f ? -4.f : x); }
static inline float knobTime(int32_t v) { return 0.001f * powf(5000.f, v / 100.f); }
static inline float knobHz(int32_t v) { return 20.f * powf(1000.f, v / 100.f); }
static inline float coefFor(float sec) { return expf(-4.6f / (sec * kSR)); }

static inline float noise(void) {
  uint32_t s = seed_;
  s ^= s << 13; s ^= s >> 17; s ^= s << 5; seed_ = s;
  return s / 2147483648.f - 1.f;
}
static inline float pulse(float t, float dt, float w) {
  float f = t + 1.f - w; if (f >= 1.f) f -= 1.f;
  return (t < w ? 1.f : -1.f) + blep(t, dt) - blep(f, dt);
}
/* 2-pole state-variable filter; tanh in the resonance path so it can self-oscillate but stays bounded. */
static inline float svf(float x, float fc, int32_t peak, float & s1, float & s2, bool hp) {
  if (fc > kSR * 0.45f) fc = kSR * 0.45f;
  const float g = tanf(kPi * fc / kSR);
  const float k = 2.f - 2.05f * (peak / 100.f);
  const float yh = (x - (k + g) * s1 - s2) / (1.f + k * g + g * g);
  const float yb = fastTanh(g * yh + s1);
  s1 = clamp4(g * yh + yb);
  const float yl = g * yb + s2;
  s2 = clamp4(g * yb + yl);
  return hp ? yh : yl;
}
static inline int32_t toQ31(float x) {
  if (x >= 0.99999f) x = 0.99999f;
  if (x <= -0.99999f) x = -0.99999f;
  return (int32_t)(x * 2147483648.f);
}
/* the note the NTS-1 is playing: whole note in the top byte, fine tuning in the bottom */
static inline float noteOf(const user_osc_param_t * const params) {
  return (float)(params->pitch >> 8) + (float)(params->pitch & 0xFF) * 0.00392156862745098f;
}

static void resetVoice(void) {
  ph1_ = ph2_ = lfoPh_ = 0.f; h1_ = h2_ = l1_ = l2_ = 0.f;
  env_ = 0.f; stage_ = 0; bend_ = 0.f; d1_ = d2_ = fbY_ = penv_ = 0.f;
}

void OSC_INIT(uint32_t platform, uint32_t api) {
  (void)platform; (void)api;
  resetVoice();
}

void OSC_NOTEON(const user_osc_param_t * const params) {
  const float n = noteOf(params);
  if (stage_ == 0) cur_ = n;
  target_ = n;
  stage_ = 1;
  penv_ = 1.f;
}

void OSC_NOTEOFF(const user_osc_param_t * const params) {
  (void)params;
  if (stage_ != 0) stage_ = 3;
}

void OSC_MUTE(const user_osc_param_t * const params) {
  (void)params;
  resetVoice();
}

void OSC_VALUE(uint16_t value) { (void)value; }

void OSC_PARAM(uint16_t index, uint16_t value) {
  switch (index) {
    case k_user_osc_param_id1: setLive(0, value); break; // CUTOFF
    case k_user_osc_param_id2: setLive(1, value); break; // RESON
    case k_user_osc_param_id3: setLive(2, value); break; // ENV
    case k_user_osc_param_id4: setLive(3, value); break; // ATTACK
    case k_user_osc_param_id5: setLive(4, value); break; // RELEASE
    case k_user_osc_param_id6: setLive(5, value); break; // VOLUME
    default:
      break;
  }
}

void OSC_CYCLE(const user_osc_param_t * const params, int32_t *yn, const uint32_t frames) {
  const int32_t * v = p_;
  const float atk = 1.f / (knobTime(v[12]) * kSR);
  const float dc = coefFor(knobTime(v[13]));
  const float sus = v[14] / 100.f;
  const float rc = coefFor(knobTime(v[15]));
  const float pc = coefFor(knobTime(v[13]) * 0.3f);
  const float gc = v[20] == 0 ? 0.f : coefFor(knobTime(v[20]) * 0.2f);
  const float lfoInc = 0.05f * powf(600.f, v[18] / 100.f) / kSR;
  const float velGain = 1.f;                   // the NTS-1 sends no key velocity
  const float fb = (v[11] / 100.f) * 2.f;
  const float rn = v[10] / 100.f;
  const float ringAmt = rn > 0.f ? rn : 0.f, noiseAmt = rn < 0.f ? -rn : 0.f;
  const float drift = (v[21] / 100.f) * 30.f;
  const float lpBase = knobHz(v[0]), hpHz = knobHz(v[2]);

  target_ = noteOf(params);

  int32_t * __restrict y = yn;
  const int32_t * const y_e = yn + frames;
  for (; y != y_e; ) {
    if (stage_ == 1) { env_ += atk; if (env_ >= 1.f) { env_ = 1.f; stage_ = 2; } }
    else if (stage_ == 2) env_ = sus + (env_ - sus) * dc;
    else if (stage_ == 3) { env_ *= rc; if (env_ < 1e-5f) { env_ = 0.f; stage_ = 0; } }
    penv_ *= pc;
    cur_ = target_ + (cur_ - target_) * gc;
    lfoPh_ += lfoInc; if (lfoPh_ >= 1.f) lfoPh_ -= 1.f;
    const float lfo = 1.f - 4.f * fabsf(lfoPh_ - 0.5f);
    d1_ += (noise() - d1_) * 0.00005f;
    d2_ += (noise() - d2_) * 0.00005f;
    const float nz = noise();
    const float base = cur_ + bend_ + penv_ * (v[17] / 100.f) * 24.f;
    const float n1 = base + d1_ * drift;
    const float n2 = base + v[6] + v[7] / 100.f + d2_ * drift;
    const float dt1 = 440.f * powf(2.f, (n1 - 69.f) / 12.f) / kSR;
    const float dt2 = 440.f * powf(2.f, (n2 - 69.f) / 12.f) / kSR;
    ph1_ += dt1; if (ph1_ >= 1.f) ph1_ -= 1.f;
    ph2_ += dt2; if (ph2_ >= 1.f) ph2_ -= 1.f;
    const float t1 = ph1_, t2 = ph2_;
    float o1;
    switch (v[4]) {
      case 0: o1 = 1.f - 4.f * fabsf(t1 - 0.5f); break;
      case 1: o1 = 2.f * t1 - 1.f - blep(t1, dt1); break;
      case 2: o1 = pulse(t1, dt1, 0.5f); break;
      default: o1 = nz;
    }
    const float sq2 = pulse(t2, dt2, 0.5f);
    float o2;
    switch (v[5]) {
      case 0: o2 = 1.f - 4.f * fabsf(t2 - 0.5f); break;
      case 1: o2 = 2.f * t2 - 1.f - blep(t2, dt2); break;
      case 2: o2 = pulse(t2, dt2, 0.25f); break;
      default: o2 = o1 * sq2;
    }
    const float mix = (o1 * v[8] + o2 * v[9]) / 100.f + ringAmt * o1 * sq2 + noiseAmt * nz;
    const float x = fastTanh(mix * 0.7f + fb * fbY_);
    float lpHz = lpBase * powf(2.f, (v[16] / 100.f) * env_ * 7.f + lfo * (v[19] / 100.f) * 3.f + ((cur_ - 60.f) / 12.f) * (v[22] / 100.f));
    if (lpHz < 20.f) lpHz = 20.f;
    const float ylp = svf(svf(x, hpHz, v[3], h1_, h2_, true), lpHz, v[1], l1_, l2_, false);
    fbY_ = fastTanh(ylp);
    const float s = fbY_ * env_ * velGain * (v[23] / 100.f) * 0.5f;
    *(y++) = toQ31(s);
  }
}
